<template>
  <div class="review-page">
    <div class="page-heading"><div><h2>合同与招投标智能审查</h2><p>文档解析 → 风险识别 → 报告生成，每一步都需要人工复核并留下审计记录。</p></div><el-tag type="warning">Human-in-the-loop</el-tag></div>
    <el-card v-if="!workflow" shadow="never"><el-alert title="上传合同、招标文件或投标响应文件" type="info" :closable="false" show-icon /><input ref="fileInput" class="file-input" type="file" multiple accept=".pdf,.docx,.txt,.md,.json,.csv,.xlsx,.xlsm" @change="pick" /><el-button type="primary" @click="fileInput?.click()">选择文档</el-button><div class="files"><el-tag v-for="file in files" :key="file.name + file.size">{{ file.name }}</el-tag></div><el-input v-model="instruction" placeholder="补充审查重点，例如：重点检查付款和违约责任" class="instruction" /><el-button type="primary" :loading="loading" :disabled="!files.length" @click="start">开始审查</el-button></el-card>
    <template v-else><el-card shadow="never" class="progress"><div class="top"><b>审查工作流 {{ workflow.workflow_id }}</b><el-tag :type="workflow.status === 'completed' ? 'success' : 'warning'">{{ workflow.status === 'completed' ? '已完成' : '待人工审核' }}</el-tag></div><el-steps :active="active" finish-status="success" align-center><el-step v-for="step in steps" :key="step.key" :title="step.title" /></el-steps></el-card><el-card v-if="workflow.status !== 'completed'" shadow="never"><template #header>待审核：{{ currentTitle }}</template><pre>{{ pretty(workflow.review?.ai_output) }}</pre><el-button type="success" :loading="loading" @click="resume('approve')">确认通过，进入下一步</el-button><el-button type="warning" plain :loading="loading" @click="resume('return')">打回当前节点</el-button></el-card><el-card v-else shadow="never"><el-result icon="success" title="文档审查完成" sub-title="审查结果已生成，人工操作和状态均已写入审计记录。" /><pre>{{ pretty(workflow.step_outputs) }}</pre><el-button @click="reset">新建审查任务</el-button></el-card></template>
  </div>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { documentReviewApi, type ReviewAction } from '@/api/documentReview'
const files=ref<File[]>([]), instruction=ref(''), loading=ref(false), workflow=ref<any>(null), fileInput=ref<HTMLInputElement|null>(null)
const steps=[{key:'step1_extract',title:'文档解析与字段抽取'},{key:'step2_risk_review',title:'条款风险识别'},{key:'step3_report',title:'审查报告生成'}]
const active=computed(()=>Math.max(0,steps.findIndex(s=>s.key===workflow.value?.current_step))); const currentTitle=computed(()=>steps[active.value]?.title || '审查')
function pick(e:Event){files.value=Array.from((e.target as HTMLInputElement).files || []);(e.target as HTMLInputElement).value=''}; function pretty(v:unknown){return JSON.stringify(v || {},null,2)}
async function start(){const form=new FormData();files.value.forEach(f=>form.append('files',f));form.append('instruction',instruction.value);loading.value=true;try{workflow.value=(await documentReviewApi.start(form)).data;ElMessage.success('已生成第一步结果，等待审核')}finally{loading.value=false}}
async function resume(action:ReviewAction){if(!workflow.value)return;loading.value=true;try{workflow.value=(await documentReviewApi.resume(workflow.value.workflow_id,action)).data;ElMessage.success(workflow.value.status==='completed'?'审查完成':'已进入下一步')}finally{loading.value=false}}; function reset(){workflow.value=null;files.value=[];instruction.value=''}
</script>
<style scoped>.review-page{max-width:1100px}.page-heading,.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}.page-heading h2{margin:0 0 6px}.page-heading p{color:#8c8c8c}.progress{margin-bottom:16px}.file-input{display:none}.files{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.instruction{margin:16px 0;display:block;max-width:620px}pre{white-space:pre-wrap;background:#f7f8fa;padding:16px;border-radius:6px;max-height:520px;overflow:auto}</style>

